mod tests {
    use super::*;
    use crate::daemon::{OwningProjectRef, WorktreeInfo};

    fn session(id: &str, title: &str, root: &str, updated_at: &str) -> SessionSummary {
        SessionSummary {
            id: id.into(),
            title: title.into(),
            cwd: root.into(),
            workspace_root: None,
            owning_project: None,
            git_branch: None,
