  width: 100%;
  max-width: 100%;
  height: var(--ctl-h);
  min-width: 0;
  padding: 0 12px;
  border: 0;
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--elev-1);
  color: var(--fg);
  font: 500 12px/1 var(--font);
  cursor: pointer;
  overflow: hidden;
  transition: background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}

.island-chip:hover,
.island-chip[aria-expanded="true"] {
  background: var(--bg-hover);
}

.island-chip:focus-visible {
  box-shadow: var(--elev-1), var(--focus-ring);
}

.island-chip__dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: var(--radius-pill);
  background: var(--accent);
}

.island-chip__dot.is-empty {
  background: var(--fg-4);
}

.island-chip.is-attention .island-chip__count {
  color: var(--warn);
}

.island-chip__dot.is-attention {
  background: var(--warn);
}

.island-chip.is-running .island-chip__count {
  color: var(--accent);
}

.island-chip__dot.is-running {
  background: var(--accent);
}

.island-live {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.island-chip__title,
.island-chip__project,
.island-chip__count {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-chip__title {
  flex: 1 1 auto;
  text-align: left;
}

.island-chip__project {
  flex: 0 1 auto;
  color: var(--fg-2);
}

.island-chip__count,
.island-chip__separator {
  flex: 0 0 auto;
  color: var(--fg-2);
}

.island-scrim {
  position: fixed;
  inset: 0;
  z-index: 120;
  background: color-mix(in srgb, var(--bg) 68%, transparent);
}

/* Left/right auto margins center the fixed surface in the usable content
   viewport. No transform is used, so opening motion can never displace it. */
.island-popover {
  position: fixed;
  top: var(--island-top);
  left: 16px;
  right: 16px;
  z-index: 121;
  width: var(--island-popover-w);
  max-height: min(620px, calc(100vh - var(--island-top) - 16px));
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  padding: 4px;
  border-radius: var(--radius-lg);
  background: var(--sheen), var(--bg-raised);
  box-shadow: var(--elev-3);
  overflow: hidden;
}

/* When the workspace splits the desktop, align the popover to the same
   remaining content/header center instead of the full window center. */
@media (min-width: 900px) {
  .has-workspace-open .island-popover {
    right: calc(var(--workspace-w) + 16px);
    width: min(560px, calc(100vw - var(--workspace-w) - 32px));
  }
}

.island-search {
  flex: 0 0 auto;
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-search__input {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 40px;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  outline: 0;
  background: transparent;
  color: var(--fg);
  caret-color: var(--accent);
  font: 400 13px/1.4 var(--font);
}

.island-search__input::placeholder {
  color: var(--fg-3);
}

.island-search__input:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-attention {
  flex: 0 1 auto;
  min-height: 0;
  margin-top: 4px;
  padding: 4px 0;
  border-bottom: 1px solid var(--border-subtle);
}

.island-attention__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 12px 4px;
  color: var(--fg-3);
  font: 600 10px/1.3 var(--font);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.island-attention__list {
  max-height: 232px;
  overflow-y: auto;
}

.island-attention__item {
  border-radius: var(--radius);
  overflow: hidden;
}

.island-attention__summary {
  appearance: none;
  display: grid;
  grid-template-columns: 104px minmax(100px, 0.75fr) minmax(0, 1fr) 16px;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 40px;
  padding: 7px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  font: 400 11px/1.35 var(--font);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.island-attention__summary:hover,
.island-attention__summary[aria-expanded="true"] {
  background: var(--bg-hover);
}

.island-attention__summary:focus-visible,
.island-attention__open:focus-visible {
  box-shadow: var(--focus-ring);
  outline: none;
}

.island-attention__state {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--fg-3);
  font-weight: 600;
}

.island-attention__state > span {
  width: 6px;
  height: 6px;
  flex: 0 0 6px;
  border-radius: var(--radius-pill);
  background: currentColor;
}

.island-attention__item.is-needs-human .island-attention__state,
.island-attention__item.is-cancelling .island-attention__state {
  color: var(--warn);
}

.island-attention__item.is-failed .island-attention__state {
  color: var(--err);
}

.island-attention__item.is-running .island-attention__state {
  color: var(--accent);
}

.island-attention__session,
.island-attention__summary-detail {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-attention__session {
  color: var(--fg);
  font-weight: 500;
}

.island-attention__summary-detail {
  color: var(--fg-3);
}

.island-attention__disclosure {
  display: inline-flex;
  width: 16px;
  height: 16px;
  align-items: center;
  justify-content: center;
  color: var(--fg-3);
  transition: transform var(--dur-fast) var(--ease);
}

.island-attention__summary[aria-expanded="true"] .island-attention__disclosure {
  transform: rotate(180deg);
}

.island-attention__disclosure svg {
  width: 12px;
  height: 12px;
}

.island-attention__details {
  padding: 7px 12px 10px 124px;
  background: var(--bg-elevated);
  color: var(--fg-2);
}

.island-attention__details p {
  max-height: 5.4em;
  margin: 5px 0 8px;
  overflow: auto;
  overflow-wrap: anywhere;
  font: 400 11px/1.5 var(--font);
}

.island-attention__meta {
  display: flex;
  min-width: 0;
  overflow: hidden;
  color: var(--fg-3);
  font: 400 10px/1.4 var(--font);
  white-space: nowrap;
}

.island-attention__meta > span {
  min-width: 0;
  max-width: 24ch;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-attention__meta > span:empty {
  display: none;
}

.island-attention__meta > span:not(:empty) ~ span:not(:empty)::before {
  content: "·";
  padding: 0 5px;
  color: var(--fg-4);
}

.island-attention__open {
  appearance: none;
  min-height: var(--ctl-h-sm);
  padding: 0 8px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  font: 500 11px/1 var(--font);
  cursor: pointer;
}

.island-attention__open:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.island-attention__open[disabled] {
  display: none;
}

.island-results {
  min-height: 0;
  max-height: min(464px, calc(100vh - var(--island-top) - 72px));
  overflow-y: auto;
  padding: 4px 0 0;
  border-radius: var(--radius);
}

.island-group {
  display: flex;
  flex-direction: column;
}

.island-result {
  appearance: none;
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.island-result:hover,
.island-result--selected {
  background: var(--bg-hover);
}

.island-result:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-result__primary,
.island-result__meta {
  display: flex;
  align-items: center;
  min-width: 0;
}

.island-result__primary {
  gap: 8px;
}

.island-result__title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
  font: 500 13px/1.35 var(--font);
}

.island-result__focused {
  flex: 0 0 auto;
  padding: 2px 5px;
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent-bright);
  font: 600 9px/1.3 var(--font);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.island-result__meta {
  gap: 0;
  margin-top: 3px;
  color: var(--fg-3);
  font: 400 10px/1.4 var(--font);
  white-space: nowrap;
  overflow: hidden;
}

.island-result__meta > span {
  min-width: 0;
  max-width: 18ch;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-result__meta > span:empty {
  display: none;
}

.island-result__meta > span:not(:empty) ~ span:not(:empty)::before {
  content: "·";
  padding: 0 5px;
  color: var(--fg-4);
}

.island-result__path {
  font-family: var(--mono);
}

.island-empty {
  padding: 28px 16px;
  color: var(--fg-3);
  font: 400 12px/1.4 var(--font);
  text-align: center;
}

/* The workspace becomes a split column at 900px and may consume up to 65%
   of the window. Keep the remaining header to the identity dot/state dots so
   the centered Island has stable reserved tracks even at that maximum. */
@media (min-width: 900px) {
  .has-workspace-open .ocean-brand__word,
  .has-workspace-open .ocean-tokens,
  .has-workspace-open .ocean-status__text,
  .has-workspace-open .ocean-browser-control__label {
    display: none;
  }
}

@media (min-width: 900px) and (max-width: 1100px) {
  .has-workspace-open .ocean-brand {
    display: none;
  }
}

@media (max-width: 1000px) {
  .island-host {
    width: min(300px, 42%);
  }

  .island-chip__project,
  .island-chip__separator {
    display: none;
  }
}

/* Below the split-view breakpoint the workspace overlays from the right.
   Center the chip in the still-visible transcript column so workspace tabs
   never paint through the titlebar control. The popover remains viewport-wide
   and above the workspace, preserving the compact overlay behavior. */
@media (max-width: 899px) {
  .has-workspace-open .island-host {
    right: var(--workspace-w);
    /* The workspace resizer may intentionally leave only a 48px context
       sliver. Collapse rather than painting through traffic lights or tabs
       when that sliver cannot safely hold the interactive titlebar control. */
    max-width: max(0px, calc(100vw - var(--workspace-w) - 160px));
  }
}

@media (min-width: 721px) and (max-width: 840px) {
  .has-workspace-open .island-host {
    max-width: max(0px, calc(100vw - var(--workspace-w) - 220px));
  }
}

@media (min-width: 841px) and (max-width: 899px) {
  .has-workspace-open .island-host {
    max-width: max(0px, calc(100vw - var(--workspace-w) - 300px));
  }
}

@media (max-width: 840px) {
  .is-titlebar .ocean-brand__word {
    display: none;
  }

  .island-host {
    width: min(240px, 38%);
  }

  .island-chip {
    padding-inline: 9px;
  }

  .island-chip__count {
    max-width: 7ch;
  }
}

@media (max-width: 720px) {
  /* compact.css is later in the cascade; this higher-specificity titlebar
     rule keeps the native traffic-light inset at the supported minimum. */
  main.ocean-surface.is-titlebar .ocean-header {
    padding-left: var(--titlebar-inset);
  }

  .island-host {
    width: min(210px, 36%);
  }

  .has-workspace-open .ocean-brand {
    display: none;
  }

  .island-chip__count {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .island-chip,
  .island-result,
  .island-attention__summary,
  .island-attention__disclosure {
    transition: none;
  }
}

text:
/* Chrome side-panel (MV3) compact layout — structural overrides only.
   The domain styles own color; this file only tightens geometry in the
   `.ocean-surface--extension` root emitted by the Leptos app. */

.ocean-surface--extension {
  max-width: none;
  width: 100%;
}

/* Header stays one row in the side panel; context chips truncate before the
   chrome wraps into a second busy toolbar. */
.ocean-surface--extension .ocean-header {
  flex-wrap: nowrap;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
}

.ocean-surface--extension .ocean-brand {
  min-width: 0;
}


.ocean-surface--extension .ocean-header__right {
  flex: 1 1 auto;
  min-width: 0;
  flex-wrap: nowrap;
  gap: 4px;
  justify-content: flex-end;
}

.ocean-surface--extension .ocean-runtime {
  flex: 0 1 auto;
  min-width: 0;
  gap: 6px;
  padding-left: 0;
  box-shadow: none;
}

.ocean-surface--extension .ocean-runtime .ocean-tokens {
  display: none;
}

.ocean-surface--extension .ocean-browser-control {
  width: var(--ctl-h-sm);
  padding: 0;
  justify-content: center;
}

.ocean-surface--extension .ocean-browser-control__label {
  display: none;
}

.ocean-surface--extension .ocean-runtime .ocean-status {
  flex: 0 1 auto;
  max-width: 96px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Header controls and per-turn selectors use compact control height. */
  .ocean-surface--extension .ocean-sessions-trigger,
  .ocean-surface--extension .ocean-thinking,
  .ocean-surface--extension .ocean-model-override {
    min-height: var(--ctl-h-sm);
    height: var(--ctl-h-sm);
  }

.ocean-surface--extension .ocean-thinking,
.ocean-surface--extension .ocean-model-override {
  max-width: 46vw;
}

/* Transcript and canvas regions keep readable gutters in a narrow column. */
.ocean-surface--extension .transcript {
  padding: 12px 14px;
  gap: 12px;
}

.ocean-surface--extension .block--text {
  max-width: 100%;
  overflow-x: auto;
}

.ocean-surface--extension .ocean-canvas {
  margin: 8px 10px 0;
}

.ocean-surface--extension .ocean-canvas__head,
.ocean-surface--extension .ocean-canvas__tabs {
  padding-right: 10px;
  padding-left: 10px;
}

/* Composer compresses without changing the base control recipes. */
.ocean-surface--extension .ocean-composer {
  padding: 8px 10px 10px;
  column-gap: 8px;
  row-gap: 4px;
}

.ocean-surface--extension .voice-wrap {
  gap: 6px;
}

.ocean-surface--extension .voice-orb {
  width: 32px;
  height: 32px;
  font-size: 16px;
}

.ocean-surface--extension .voice-hint {
  display: none;
}

/* Voice menu + live chip fit the narrow side panel; the chip collapses to
   its pulsing dot at this width, and the trigger keeps a findable floor. */
.ocean-surface--extension .voice-menu {
  max-width: min(224px, calc(100vw - 24px));
}

.ocean-surface--extension .voice-live-chip {
  font-size: 0;
  gap: 0;
  padding: 4px;
}

.ocean-surface--extension .voice-trigger {
  opacity: 0.35;
}

.ocean-surface--extension .ocean-composer__input {
  min-width: 0;
}

.ocean-surface--extension .ocean-composer__halt,
.ocean-surface--extension .ocean-composer__send {
  min-height: var(--ctl-h-sm);
  height: var(--ctl-h-sm);
}

/* ── Normal web surface compact mode (header chips + composer first) ── */
@media (max-width: 720px) {
  /* Root: fill viewport, drop the central max-width gutter -------------- */
  .ocean-surface {
    max-width: none;
    width: 100%;
  }

  /* Header: single row, chips truncate before a 2nd toolbar wraps ----- */
  .ocean-surface .ocean-header {
    flex-wrap: nowrap;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
  }

  .ocean-surface .ocean-brand {
    min-width: 0;
  }

  .ocean-surface .ocean-header__right {
    flex: 1 1 auto;
    min-width: 0;
    flex-wrap: nowrap;
    gap: 4px;
    justify-content: flex-end;
  }

  .ocean-surface .ocean-runtime {
    flex: 0 1 auto;
    min-width: 0;
    gap: 6px;
    padding-left: 0;
    box-shadow: none;
  }

  .ocean-surface .ocean-runtime .ocean-tokens {
    display: none;
  }

  .ocean-surface .ocean-browser-control {
    width: var(--ctl-h-sm);
    padding: 0;
    justify-content: center;
  }

  .ocean-surface .ocean-browser-control__label {
    display: none;
  }

  .ocean-surface .ocean-runtime .ocean-status {
    flex: 0 1 auto;
    max-width: 96px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Controls: compact height, capped chip widths ---------------------- */
  .ocean-surface .ocean-sessions-trigger,
  .ocean-surface .ocean-thinking,
  .ocean-surface .ocean-model-override {
    min-height: var(--ctl-h-sm);
    height: var(--ctl-h-sm);
  }

  .ocean-surface .ocean-thinking,
  .ocean-surface .ocean-model-override {
    max-width: 46vw;
  }

  /* Transcript & canvas: readable gutters ---------------------------- */
  .ocean-surface .transcript {
    padding: 12px 14px;
    gap: 12px;
  }

  .ocean-surface .block--text {
    max-width: 100%;
    overflow-x: auto;
  }

  .ocean-surface .ocean-canvas {
    margin: 8px 10px 0;
  }

  .ocean-surface .ocean-canvas__head,
  .ocean-surface .ocean-canvas__tabs {
    padding-right: 10px;
    padding-left: 10px;
  }

  /* Composer: tighter padding, smaller orb, no hint ---------------- */
  .ocean-surface .ocean-composer {
    padding: 8px 10px 10px;
    column-gap: 8px;
    row-gap: 4px;
  }

  .ocean-surface .voice-wrap {
    gap: 6px;
  }

  .ocean-surface .voice-orb {
    width: 32px;
    height: 32px;
    font-size: 16px;
  }

  .ocean-surface .voice-hint {
    display: none;
  }

  /* Voice menu + trigger keep their narrow-width behavior under 720px. */
  .ocean-surface .voice-menu {
    max-width: min(224px, calc(100vw - 24px));
  }

  .ocean-surface .voice-trigger {
    opacity: 0.35;
  }

  .ocean-surface .voice-live-chip {
    gap: 0;
    padding: 4px;
    font-size: 0;
  }

  .ocean-surface .ocean-composer__input {
    min-width: 0;
  }

  .ocean-surface .ocean-composer__halt,
  .ocean-surface .ocean-composer__send {
    min-height: var(--ctl-h-sm);
    height: var(--ctl-h-sm);
  }

  /* Rich content: clip instead of widening viewport ------------------ */
  .ocean-surface pre,
  .ocean-surface img,
  .ocean-surface table {
    max-width: 100%;
    overflow-x: auto;
  }
}

/* Wide rich content clips in the side panel instead of widening it. */
.ocean-surface--extension pre,
.ocean-surface--extension img,
.ocean-surface--extension table {
  max-width: 100%;
  overflow-x: auto;
}

/* ── Narrow component reflow (≤480px) — stack kanban, cardify tables,
   full-width charts, single-col stats/dashboards. True reflow, not
   overflow-x band-aids. ─────────────────────────────────────────────── */
@media (max-width: 480px) {
  /* Container: prevent turn body from growing past viewport --------- */
  .ocean-surface .turn--assistant .turn__body {
    min-width: 0;
    overflow: hidden;
  }

  /* All component wrappers: fill the turn body, don't push offscreen */
  .ocean-surface .component-kanban,
  .ocean-surface .component-form,
  .ocean-surface .component-table,
  .ocean-surface .component-progress,
  .ocean-surface .component-markdown,
  .ocean-surface .component-dashboard,
  .ocean-surface .component-chart,
  .ocean-surface .component-timeline,
  .ocean-surface .component-stats,
  .ocean-surface .component-filetree,
  .ocean-surface .component-diff,
  .ocean-surface .component-code,
  .ocean-surface .component-callout,
  .ocean-surface .component-gallery,
  .ocean-surface .component-confirm,
  .ocean-surface .block--map,
  .ocean-surface .block--video,
  .ocean-surface .block--component-unknown {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
  }

  /* Kanban: stack columns vertically -------------------------------- */
  .ocean-surface .kanban-columns {
    flex-direction: column;
    gap: 12px;
    max-height: none;
    overflow-x: visible;
  }
  .ocean-surface .kanban-column {
    min-width: 0;
    max-width: none;
    flex: 1 1 auto;
    width: 100%;
  }

  /* Table: cardify rows — hide thead, display tr/td as blocks ----- */
  .ocean-surface .component-table {
    overflow-x: visible;
  }
  .ocean-surface .data-table {
    display: block;
    min-width: 0;
    width: 100%;
  }
  .ocean-surface .data-table thead {
    display: none;
  }
  .ocean-surface .data-table tbody {
    display: block;
  }
  .ocean-surface .data-table__row {
    display: block;
    margin-bottom: 6px;
    background: var(--bg-elevated);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius);
  }
  .ocean-surface .data-table td {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 8px;
    padding: 6px 12px;
    border-bottom: none;
    text-align: right;
  }
