--- staged ---
--- plans ---
--- css diff ---
diff --git a/styles/island.css b/styles/island.css
new file mode 100644
index 0000000..6b32468
--- /dev/null
+++ b/styles/island.css
@@ -0,0 +1,585 @@
+/* Dynamic Island — native titlebar session focus/search. Tauri-only in the
+   component tree; these selectors remain inert on web and extension hosts. */
+
+:root {
+  --island-max-w: 520px;
+  --island-popover-w: min(560px, calc(100vw - 32px));
+  --island-top: 64px;
+}
+
+.ocean-header {
+  position: relative;
+}
+
+.ocean-header__left {
+  display: flex;
+  align-items: center;
+  min-width: 0;
+}
+
+/* Center inside the real header/content column without transform. Fixed
+   descendants therefore stay viewport-fixed instead of inheriting a new
+   containing block. The percentage cap reserves both titlebar control zones. */
+.island-host {
+  position: absolute;
+  inset-inline: 0;
+  top: 11px;
+  width: min(var(--island-max-w), 44%);
+  height: var(--ctl-h);
+  margin-inline: auto;
+  z-index: 122;
+}
+
+.island-chip {
+  box-sizing: border-box;
+  position: relative;
+  z-index: 122;
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  width: 100%;
+  max-width: 100%;
+  height: var(--ctl-h);
+  min-width: 0;
+  padding: 0 12px;
+  border: 0;
+  border-radius: var(--radius);
