   514	/* Below the split-view breakpoint the workspace overlays from the right.
   515	   Center the chip in the still-visible transcript column so workspace tabs
   516	   never paint through the titlebar control. The popover remains viewport-wide
   517	   and above the workspace, preserving the compact overlay behavior. */
   518	@media (max-width: 899px) {
   519	  .has-workspace-open .island-host {
   520	    right: var(--workspace-w);
   521	    /* The workspace resizer may intentionally leave only a 48px context
   522	       sliver. Collapse rather than painting through traffic lights or tabs
   523	       when that sliver cannot safely hold the interactive titlebar control. */
   524	    max-width: max(0px, calc(100vw - var(--workspace-w) - 160px));
   525	  }
   526	}
